import * as React from "react"
import { cn } from '@/lib/utils'

/*
 * GENERATED BY `shadcn add card`, WITH TWO VALUES IN THE ROOT CLASS CHANGED.
 *
 *   rounded-xl -> rounded-lg   `--radius-xl` is 14px here, following shadcn's
 *                              own convention of one step above `--radius`.
 *                              Card SURFACES are 10px and always have been,
 *                              which is `--radius-lg`. Both are decided in
 *                              `docs/migration/shadcn/_decisions.md`.
 *   shadow-sm  -> (dropped)    This app has exactly two shadows and both are
 *                              on things that FLOAT over the page -- the help
 *                              bubble and the chart tooltip. A shadow is what
 *                              distinguishes those from the surface they
 *                              cover, so giving every panel one would spend
 *                              the only cue they have. Flat is a decision,
 *                              not an omission.
 *
 * A CARD MAY NOT CLIP, AND MAY NOT BECOME A CONTAINING BLOCK. `Help.tsx`'s
 * bubble is `position: fixed` and placed from `getBoundingClientRect()` in
 * viewport coordinates, so an ancestor with `overflow: hidden` cuts it in
 * half -- which is what happened the first time this was built -- and an
 * ancestor with `transform`, `filter`, `will-change`, `contain` or
 * `container-type` makes it land somewhere else entirely. That last one is
 * why `CardHeader` is unused in this project: its class begins
 * `@container/card-header`, which is `container-type: inline-size`, which is
 * layout containment, which is a containing block for a fixed descendant.
 * The incident record lists the other four and not that one, which is
 * exactly how it would have slipped through. Doc 20 removes the constraint
 * by making the bubble a portalled Popover; until then it is live.
 */
function Card({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="card"
      className={cn(
        "flex flex-col gap-6 rounded-lg border bg-card py-6 text-card-foreground",
        className
      )}
      {...props}
    />
  )
}

function CardHeader({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="card-header"
      className={cn(
        "@container/card-header grid auto-rows-min grid-rows-[auto_auto] items-start gap-2 px-6 has-data-[slot=card-action]:grid-cols-[1fr_auto] [.border-b]:pb-6",
        className
      )}
      {...props}
    />
  )
}

function CardTitle({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="card-title"
      className={cn("leading-none font-semibold", className)}
      {...props}
    />
  )
}

function CardDescription({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="card-description"
      className={cn("text-sm text-muted-foreground", className)}
      {...props}
    />
  )
}

function CardAction({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="card-action"
      className={cn(
        "col-start-2 row-span-2 row-start-1 self-start justify-self-end",
        className
      )}
      {...props}
    />
  )
}

function CardContent({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="card-content"
      className={cn("px-6", className)}
      {...props}
    />
  )
}

function CardFooter({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="card-footer"
      className={cn("flex items-center px-6 [.border-t]:pt-6", className)}
      {...props}
    />
  )
}

export {
  Card,
  CardHeader,
  CardFooter,
  CardTitle,
  CardAction,
  CardDescription,
  CardContent,
}
